; F1 (BRKI 0: IN / OUT trap to vector 19 (measured for F2; not in the F1 gate)). Generated by validation/v35s/onchip.py emit: the
; image also preloads the vector stubs and the data in onchip.py.
    BR main
handler:                ; 0103h: AL = the vector (from the stub)
    MOV BL, AL
    XOR AW, AW
    MOV DS0, AW
    MOV [7E00h], BL
    MOV BP, SP
    MOV AW, [BP]
    MOV [7E02h], AW
    MOV AW, [BP+2]
    MOV [7E04h], AW
    MOV AW, [BP+4]
    MOV [7E06h], AW
    MOV [7E08h], SP
    MOV AH, 02h         ; BRKI = 1: the OUT below does not trap
    MOV PSW, AH
    MOV DW, 0FF02h
    OUT DW, AL
    HALT
hspin:
    BR hspin
main:
    XOR AW, AW
    MOV SS, AW
    MOV SP, 7FFEh
    DI

    MOV AW, 0800h
    MOV DS0, AW
    MOV word [0000h], 0000h
    ; 1. SAHF 00 then IN at once
    MOV AL, 11h
    MOV AH, 00h
    MOV PSW, AH
    IN AL, 22h
    MOV [0010h], AL
    MOV AH, 02h
    MOV PSW, AH
    ; 2. SAHF 00, NOP, IN
    MOV AL, 12h
    MOV AH, 00h
    MOV PSW, AH
    NOP
    IN AL, 22h
    MOV [0011h], AL
    MOV AH, 02h
    MOV PSW, AH
    ; 3. SAHF 00 then OUT at once
    MOV AL, 33h
    MOV AH, 00h
    MOV PSW, AH
    OUT 22h, AL
    MOV AH, 02h
    MOV PSW, AH
    ; 4. SAHF 00, NOP, OUT
    MOV AL, 34h
    MOV AH, 00h
    MOV PSW, AH
    NOP
    OUT 22h, AL
    MOV AH, 02h
    MOV PSW, AH
    ; 5. POP PSW 0000, IN AW,DW at once
    MOV DW, 0024h
    MOV AW, 0000h
    PUSH AW
    POP PSW
    IN AW, DW
    MOV [0012h], AW
    MOV AH, 02h
    MOV PSW, AH
    ; 6. POP PSW 0000, OUT DW,AW at once
    MOV AW, 0000h
    PUSH AW
    MOV AW, 4455h
    POP PSW
    OUT DW, AW
    PUSH PSW
    POP CW
    MOV [0014h], CW
    MOV DW, 0FF00h
    OUT DW, AL
    HALT
done:
    BR done

